const c="https://router.project-osrm.org";class d{static async calculateRoute(a){if(a.length<2)return{feasible:!1};const n=a.map(t=>`${t.lng},${t.lat}`).join(";"),i=`${c}/route/v1/driving/${n}?overview=false&steps=false`;try{const t=await fetch(i,{signal:AbortSignal.timeout(5e3)});if(!t.ok)return{feasible:!1};const s=await t.json();if(s.code!=="Ok"||!s.routes||s.routes.length===0)return{feasible:!1};const r=s.routes[0];return{feasible:!0,legs:(r.legs||[]).map((e,o)=>({distance:{value:e.distance,text:e.distance>=1e3?`${(e.distance/1e3).toFixed(1)} km`:`${e.distance.toFixed(0)} m`},duration:{value:e.duration,text:`${Math.round(e.duration/60)} min`},start_location:a[o],end_location:a[o+1]})),totalDistance:r.distance,totalDuration:r.duration}}catch{return{feasible:!1}}}}export{d as OSRMService};
